  document.getElementById('runBtn').disabled = true;
  setStatus('running…', '#555');
  document.getElementById('heapLog').value = '';
  frames = [];
  frameIndex = 0;
  updatePlaybackUi();

  if (activeWorker) activeWorker.terminate();
  var workerSrc = buildWorkerSource();
  var blob = new Blob([workerSrc], { type: 'application/javascript' });
  var url = URL.createObjectURL(blob);
  activeWorker = new Worker(url);
  URL.revokeObjectURL(url);

  var timedOut = false;
  var timeoutId = setTimeout(function () {
    timedOut = true;
    if (activeWorker) activeWorker.terminate();
    document.getElementById('runBtn').disabled = false;
    frames = [{ kind: 'error', state: inputVals, indices: [], message: 'Error: execution timed out. Check for infinite recursion or loops.' }];
    frameIndex = 0;
    renderCurrentFrame();
    setStatus('error: timed out', '#9b0000');
    activeWorker = null;
  }, 1800);

  activeWorker.onmessage = function (e) {
    if (timedOut) return;
    clearTimeout(timeoutId);
    document.getElementById('runBtn').disabled = false;
    activeWorker = null;
    frames = e.data.frames || [];
    if (!frames.length) frames = [{ kind: 'error', state: inputVals, indices: [], message: 'No frames were recorded.' }];
    var finalFrame = frames[frames.length - 1];
    if (e.data.error) {
      setStatus('error', '#9b0000');
    } else {
      var bad = heapViolations(finalFrame.state);
      if (bad.length) {
        finalFrame.kind = 'wrong';
        finalFrame.indices = bad;
        finalFrame.message = 'Wrong answer: at least one parent is smaller than a child. The highlighted indices violate the max-heap property.';
        setStatus('wrong answer', '#9b0000');
      } else {
        finalFrame.kind = 'done';
        finalFrame.message = 'Correct: every parent is at least as large as its children.';
        setStatus('correct', '#157a28');
      }
    }
    frameIndex = 0;
    renderCurrentFrame();
    updateLog();
  };

  activeWorker.onerror = function (e) {
    if (timedOut) return;
    clearTimeout(timeoutId);
    document.getElementById('runBtn').disabled = false;
    activeWorker = null;
    frames = [{ kind: 'error', state: inputVals, indices: [], message: 'Worker error: ' + (e.message || 'unknown error') }];
    frameIndex = 0;
    renderCurrentFrame();
    setStatus('error', '#9b0000');
  };

  activeWorker.postMessage({ code: code, input: inputVals });
}

function buildWorkerSource() {
  return [
    'onmessage=function(ev){',
    'var code=ev.data.code,input=ev.data.input;',
    'var frames=[],A=[null].concat(input),n=input.length,currentMark=null,currentLabel="",buildRoot=null,ops=0,maxOps=6000,maxFrames=1600;',
    'function snap(){return A.slice(1);}',
    'function checkIndex(i){if(!Number.isInteger(i)||i<1||i>n)throw new Error("index "+i+" is outside 1.."+n);}',
    'function add(kind,indices,message,extra){ops++; if(ops>maxOps)throw new Error("operation limit exceeded"); if(frames.length>=maxFrames)throw new Error("frame limit exceeded"); var f={kind:kind,state:snap(),indices:(indices||[]).slice(),message:String(message||""),markIndex:currentMark,markLabel:currentLabel,buildRoot:buildRoot}; if(extra){for(var k in extra)f[k]=extra[k];} frames.push(f);}',
    'function left(i){checkIndex(i); var v=2*i; add("left",[i],"left("+i+") = "+v); return v;}',
    'function right(i){checkIndex(i); var v=2*i+1; add("right",[i],"right("+i+") = "+v); return v;}',
    'function value(i){checkIndex(i); add("value",[i],"read A["+i+"] = "+A[i]); return A[i];}',
    'function greater(i,j){checkIndex(i); checkIndex(j); var res=A[i]>A[j]; add("greater",[i,j],"compare A["+i+"]="+A[i]+" with A["+j+"]="+A[j]+" \\u2192 "+res,{compare:[i,j]}); return res;}',
    'function swap(i,j){checkIndex(i); checkIndex(j); var ai=A[i],aj=A[j]; var t=A[i]; A[i]=A[j]; A[j]=t; add("swap",[i,j],"swap A["+i+"]="+ai+" with A["+j+"]="+aj,{swap:[i,j]});}',
    'function mark(i,label){checkIndex(i); currentMark=i; currentLabel=String(label||"i").slice(0,8); add("mark",[i],"mark index "+i+" as "+currentLabel);}',
    'try{',
    'var factory=new Function("left","right","value","greater","swap","mark", code+"\\n; return (typeof maxHeapify===\\"function\\") ? maxHeapify : null;");',
    'var maxHeapify=factory(left,right,value,greater,swap,mark);',
    'if(typeof maxHeapify!=="function")throw new Error("Define function maxHeapify(i, heapSize).");',
    'add("start",[],"Initial array. BUILD-MAX-HEAP will call MAX-HEAPIFY from floor(n/2) down to 1.");',
    'for(var i=Math.floor(n/2);i>=1;i--){buildRoot=i; currentMark=i; currentLabel="i"; add("call",[i],"BUILD-MAX-HEAP calls maxHeapify("+i+", "+n+")."); maxHeapify(i,n);}',
    'buildRoot=null; currentMark=null; currentLabel=""; add("done",[],"BUILD-MAX-HEAP finished.");',
    'postMessage({frames:frames,final:snap()});',
    '}catch(err){try{add("error",[],"Error: "+(err&&err.message?err.message:err));}catch(e){} postMessage({frames:frames,error:String(err&&err.message?err.message:err),final:snap()});}',
    '}'
  ].join('');
}

function heapViolations(arr) {
  var bad = [];
  for (var i = 1; i <= Math.floor(arr.length / 2); i++) {
    var l = 2 * i, r = 2 * i + 1;
    if (l <= arr.length && arr[i - 1] < arr[l - 1]) { bad.push(i); bad.push(l); }
    if (r <= arr.length && arr[i - 1] < arr[r - 1]) { bad.push(i); bad.push(r); }
  }
  var seen = {};
  return bad.filter(function (x) { if (seen[x]) return false; seen[x] = true; return true; });
}

function setStatus(text, color) {
  var el = document.getElementById('statusText');
  el.textContent = text;
  el.style.color = color || '#555';
}

function renderCurrentFrame() {
  if (!frames.length) return;
  frameIndex = Math.max(0, Math.min(frames.length - 1, frameIndex));
  drawSingleFrame(frames[frameIndex]);
  updatePlaybackUi();
}

function updatePlaybackUi() {
  document.getElementById('frameCounter').textContent = frames.length ? ((frameIndex + 1) + ' of ' + frames.length) : '0 of 0';
  document.getElementById('frameCaption').textContent = frames.length ? frames[frameIndex].message : '';
}

function updateLog() {
  var lines = frames.map(function (f, i) { return (i + 1) + '. ' + f.message; });
  document.getElementById('heapLog').value = lines.join('\n');
}

function firstFrame() { if (frames.length) { frameIndex = 0; renderCurrentFrame(); } }
function prevFrame() { if (frames.length) { frameIndex = Math.max(0, frameIndex - 1); renderCurrentFrame(); } }
function nextFrame() { if (frames.length) { frameIndex = Math.min(frames.length - 1, frameIndex + 1); renderCurrentFrame(); } }

function togglePlay() {
  if (playTimer) {
    stopPlay();
    return;
  }
  if (!frames.length) return;
  document.getElementById('playBtn').textContent = '❚❚';
  var speed = Number(document.getElementById('speedInput').value || 3);
  var delay = Math.max(120, 900 - speed * 140);
  playTimer = setInterval(function () {
    if (frameIndex >= frames.length - 1) {
      stopPlay();
    } else {
      frameIndex++;
      renderCurrentFrame();
    }
  }, delay);
}

function stopPlay() {
  if (playTimer) clearInterval(playTimer);
  playTimer = null;
  document.getElementById('playBtn').textContent = '▶';
}

document.getElementById('heapifyEditorCode').value = sampleCode;
setStep(0);
updatePlaybackUi();
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

FAITHFULNESS FIRST: the default state must be a pixel-accurate inline replacement for the source image — same colors, same data shape, same labels, same proportions. A student who sees the static figure in the textbook should recognize it immediately.

THEN ADD INTERACTIVITY: implement any controls from blueprint.interactions so a student can explore the concept hands-on. Each control's handler should teach the relationship described in its "teaches" field. Use hover tooltips and click popups to surface explanations on demand.

CONCEPT: BUILD-MAX-HEAP turns an arbitrary array into a max-heap in place by calling MAX-HEAPIFY on each internal node from the last parent back to the root.
KEY INSIGHT (what students should walk away understanding): BUILD-MAX-HEAP works bottom-up because MAX-HEAPIFY is correct only when the node's left and right subtrees are already heaps.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "BUILD-MAX-HEAP turns an arbitrary array into a max-heap in place by calling MAX-HEAPIFY on each internal node from the last parent back to the root.",
  "figureType": "diagram",
  "elements": [
    "top horizontal array bar labeled A with ten cells containing 4, 1, 3, 2, 16, 9, 10, 14, 8, 7",
    "binary tree representation of the same 1-indexed array",
    "tree node 1 with key value 4",
    "tree node 2 with key value 1",
    "tree node 3 with key value 3",
    "tree node 4 with key value 2",
    "tree node 5 with key value 16",
    "tree node 6 with key value 9",
    "tree node 7 with key value 10",
    "tree node 8 with key value 14",
    "tree node 9 with key value 8",
    "tree node 10 with key value 7",
    "small external index labels 1 through 10 beside or above each tree node",
    "tree edge from node 1 to node 2",
    "tree edge from node 1 to node 3",
    "tree edge from node 2 to node 4",
    "tree edge from node 2 to node 5",
    "tree edge from node 3 to node 6",
    "tree edge from node 3 to node 7",
    "tree edge from node 4 to node 8",
    "tree edge from node 4 to node 9",
    "tree edge from node 5 to node 10",
    "light gray fill for ordinary heap nodes",
    "dark gray fill for the current root i being heapified",
    "italic label i beside the current node",
    "comparison arrows from the current candidate node to its children during MAX-HEAPIFY",
    "swap highlight on the two nodes and two array cells being exchanged",
    "call-order/checkpoint labels corresponding to panels (a) through (f)",
    "final max-heap state with root 16 and no dark current-node highlight"
  ],
  "interactions": [
    {
      "id": "heapifyEditor",
      "type": "code_editor",
      "label": "Implement MAX-HEAPIFY and run BUILD-MAX-HEAP",
      "entry_point": "maxHeapify(i, heapSize)",
      "api": [
        {
          "op": "left(i)",
          "does": "return the 1-indexed left child index 2*i"
        },
        {
          "op": "right(i)",
          "does": "return the 1-indexed right child index 2*i + 1"
        },
        {
          "op": "value(i)",
          "does": "read A[i] and visually highlight that array cell and tree node"
        },
        {
          "op": "greater(i, j)",
          "does": "return true when A[i] > A[j] and draw a comparison arrow between the two tree nodes"
        },
        {
          "op": "swap(i, j)",
          "does": "exchange A[i] and A[j] in both the array bar and tree; this is the only way to mutate the heap"
        },
        {
          "op": "mark(i, label)",
          "does": "shade node i dark gray and place the given label beside it, usually label 'i'"
        }
      ],
      "frame": "Each recorded frame shows the full array bar and matching binary tree, with the current heapify root shaded dark gray, comparison arrows to children, and highlighted swaps; the runner calls the learner's maxHeapify for i = floor(n/2), floor(n/2)-1, ..., 1.",
      "input": {
        "label": "Initial array",
        "default": "4, 1, 3, 2, 16, 9, 10, 14, 8, 7"
      },
      "sample_code": "function maxHeapify(i, heapSize) {\n  mark(i, \"i\");\n  let l = left(i);\n  let r = right(i);\n  let largest = i;\n\n  if (l <= heapSize && greater(l, largest)) {\n    largest = l;\n  }\n  if (r <= heapSize && greater(r, largest)) {\n    largest = r;\n  }\n\n  if (largest !== i) {\n    swap(i, largest);\n    maxHeapify(largest, heapSize);\n  }\n}",
      "buggy_code": "function maxHeapify(i, heapSize) {\n  // BUG: performs at most one swap, but does not continue sifting down.\n  mark(i, \"i\");\n  let l = left(i);\n  let r = right(i);\n  let largest = i;\n\n  if (l <= heapSize && greater(l, largest)) {\n    largest = l;\n  }\n  if (r <= heapSize && greater(r, largest)) {\n    largest = r;\n  }\n\n  if (largest !== i) {\n    swap(i, largest);\n  }\n}",
      "success_check": "After the runner finishes BUILD-MAX-HEAP, every parent index i has A[i] >= A[left(i)] and A[i] >= A[right(i)] whenever those children exist.",
      "teaches": "The learner sees that BUILD-MAX-HEAP is not a global rearrangement at once: each MAX-HEAPIFY call assumes its child subtrees are already heaps, fixes one rooted subtree by sifting a value downward, and leaves a larger heap behind."
    }
  ],
  "demo_steps": [
    {
      "title": "Array as a tree",
      "narration": "The same ten values are shown twice: as the array A and as a complete binary tree using 1-indexed heap positions. Parent-child links come entirely from array indices, not from pointer structure.",
      "state": {}
    },
    {
      "title": "Start at the last internal node",
      "narration": "BUILD-MAX-HEAP begins at i = floor(n/2) = 5 because nodes 6 through 10 are leaves and are already one-node heaps. The first MAX-HEAPIFY call checks whether the subtree rooted at index 5 needs repair.",
      "state": {}
    },
    {
      "title": "Move backward through parents",
      "narration": "The runner calls MAX-HEAPIFY at i = 4, then 3, then 2, then 1. After each call, the subtree rooted at that index satisfies the max-heap property.",
      "state": {}
    },
    {
      "title": "Watch comparisons choose the largest child",
      "narration": "During MAX-HEAPIFY, comparison arrows show how the algorithm chooses the largest among a node and its children. A swap happens only when a child is larger than the current root of that subtree.",
      "state": {}
    },
    {
      "title": "Sift down until the subtree is fixed",
      "narration": "If a swap moves the original value downward, MAX-HEAPIFY must continue recursively at the child position. Omitting this recursive sift-down can leave a violation lower in the subtree.",
      "state": {}
    },
    {
      "title": "Completed max-heap",
      "narration": "When the final call at i = 1 finishes, the largest value 16 has risen to the root and every parent is at least as large as its children. The array now represents a valid max-heap in place.",
      "state": {}
    }
  ],
  "keyInsight": "BUILD-MAX-HEAP works bottom-up because MAX-HEAPIFY is correct only when the node's left and right subtrees are already heaps.",
  "reconstructionNotes": "Use a clean black-and-white CLRS-style layout: a horizontal array bar on top labeled A, and beneath it a complete binary tree with circular light-gray nodes. Put each key value large inside its circle and each array index as a small label just outside the node. Use dark gray only for the current node i. Show the tree dynamically in one main panel rather than six static panels, but include checkpoint labels or a progress strip for the original states (a) through (f): i=5, i=4, i=3, i=2, i=1, and final heap. Swaps should visibly update both the array cells and the corresponding tree nodes so learners connect the in-place array mutation to the tree shape."
}

systemPrompt:
You are a strict critic of generated inline-interactive 2D figures (SVG.js / Chart.js / Mermaid) against the original 2D textbook figure image.
You will receive the original source figure image, the generated HTML/JavaScript code, and a rendered screenshot of the generated HTML (if screenshot capture succeeds). Start by using the screenshot to help evaluate the faithfulness of the generated figure to the source figure, listing discrepancies in the primitive elements between what you see in the source figure versus what you see in the generated figure. If the screenshot was not received, mention this in the notes.
Score the generated figure using the rubric and give feedback to improve the figure. Be critical and honest — err toward lower scores when in doubt. The default (step-0) state should read as a drop-in replacement for the static source image. Do not give credit for things that are absent or barely present. Output ONLY a valid JSON object — no explanation, no markdown, no fences.

AUTOMATED VERIFICATION ALREADY PASSED — do NOT re-check these (a separate deterministic verifier renders the figure headless at multiple viewports and has already confirmed them, so this figure is guaranteed to):
- run without uncaught exceptions or page errors;
- produce a visual root (an SVG, canvas, or Mermaid diagram) that is present and visible, containing real text or graphics rather than an empty frame;
- fit the viewport: no horizontal overflow, and the main visual on-screen and not clipped at wide widths.
Therefore do NOT spend scores, failure modes, discrepancies, or action items on mechanical/runtime issues (blank output, crashes, script errors, page overflow). Focus ENTIRELY on SEMANTIC FIDELITY to the source: correct 2D structure vs the source, correct mark types, faithful composition/colors, correct and meaningful labels (right text on the right element, matching the source), meaningful and conceptually-correct interactions, and concept accuracy. Judge whether it is the *right* figure and a good teaching artifact — not whether it renders.
IMPORTANT — the 2D verifier performs NO label checks whatsoever: there is no on-screen check, no label-size check, and no label-overlap check. Label placement is therefore fully IN SCOPE for you. Do flag labels that collide with each other or with the artwork, escape the plot/diagram area, are clipped at the edge, or are too small to read comfortably at inline size.

SCAFFOLD CONTEXT (provided automatically — do not penalise for missing these):
- SVG.js v3, Chart.js v4, Mermaid v11 and expr-eval are preloaded; #container, window.__markRendered() and the 'fig-resize' event are pre-wired
- #ui is an auto-docking control panel; setUiLayout(...) positions it
- showPopup(...), showTooltip(...), hideTooltip() — built-in explainer and tooltip affordances
- Plotting helpers: setPlotFrame(...), plotX(...) / plotY(...) for data→pixel mapping, plotFunction(...), fillBetween(...), plotParametric(...), integrateSimpson(...), findRoot(...)
- compileExpr(...) and bindEquationInput(...) — live user-editable equation inputs
- Generated code may add controls, panels, and UI affordances as needed to support the planned interactions

DISCREPANCIES - list 0-6 visual discrepancies between the source figure and the generated figure, prioritized by impact on recognizability and concept accuracy
- Focus on: wrong mark types, missing or incorrect elements, wrong colors, missing or mislabeled annotations, broken or absent interactions
- De-prioritize: exact crop/zoom, whitespace variation, small differences in font face or padding — only flag these if they make the figure hard to recognize or misleading

FAILURE MODES — list any that apply (use empty array [] if none):
"Missing-Labels"          — important text annotations are absent
"Wrong-Primitives"        — incorrect geometric shapes used for the concept
"Interaction-Broken"      — interactive controls are present but non-functional
"Interaction-Missing"     — no meaningful interactions beyond pan/zoom or hover tooltips
"Scale-Wrong"             — element proportions are noticeably off
"Color-Wrong"             — colors don't match the original figure
"Hallucination"           — elements present that do not appear in the original
"Concept-Misunderstood"   — the core concept being illustrated is    misrepresented

SCORES — integer 1–5 for each field:
geometry_accuracy — Judge 2D structural fidelity against the source: axis ranges, tick marks and gridlines, the shape and trend of the data, node-and-edge topology and counts, relative proportions and layout, and line styling (dashed vs solid, stroke weight, arrowheads, fill vs outline). Flag "Wrong-Primitives" and cap the score when a major element uses the wrong mark type — e.g. a scatter drawn as a connected line, a bar chart drawn as an area, a directed edge drawn without its arrowhead, a smooth curve drawn as straight segments. This is a 2D figure: do NOT penalise the absence of depth, perspective, or a 3D vantage point.
  5 – All elements represented; plausible positions, connections, proportions
  4 – All major elements present; minor position/alignment issues
  3 – 1-2 elements missing OR noticeable spatial errors; concept still recognizable
  2 – Multiple missing elements OR major spatial errors
  1 – Unrecognizable or completely wrong topology

interactivity_usability — CRITICAL: panning or zooming the figure does NOT count as an interaction, and a hover tooltip on its own is weak. Meaningful interactions = sliders, toggles, buttons, demo-step players, equation inputs, or code-editor workbenches built by the developer, whose handlers actually redraw the figure.
  5 – All planned interactions functional and pedagogically useful; count matches figure complexity (1 deep slider is correct for a single-variable concept; 3+ expected for multi-step figures); demo steps present if the plan includes them
  4 – Most planned interactions functional; minor usability issues; pedagogical value clear
  3 – At least one meaningful interaction works; some planned interactions missing or broken; or interactions only weakly connected to the concept
  2 – Interactions exist in code but broken or no visible effect
  1 – Only pan/zoom or a bare hover tooltip present, or no interactions at all — score MUST be 1

faithfulness:
  5 – Clearly recognizable as the same figure: correct geometry, colors, composition, and major labels all present
  4 – Recognizable at a glance; minor differences in color, proportion, or label placement
  3 – General idea clear but notable differences in geometry, composition, or missing elements
  2 – Hard to recognize as the same figure; significant content differences
  1 – Completely different or fabricated

label_quality — Label placement is NOT screened by the verifier for 2D figures — judge it fully. Judge three things: (1) CONTENT — are the right labels present, with correct text, attached to the correct element, matching the source figure; (2) PLACEMENT — do labels collide with each other or with the artwork, escape the plot/diagram area, or get clipped at the edge; (3) LEGIBILITY AND HIERARCHY — are labels sized comfortably to read at inline size (text that reads as cramped or too small to read comfortably is a real defect), and does label sizing read as a deliberate, consistent hierarchy (primary/subject labels standing out over secondary/axis labels) matching what the source figure implies.
  5 – All the right labels present, correct text on the correct elements, matching the source, cleanly placed without collisions, AND sized/styled for easy legibility with a clear hierarchy matching the source
  4 – Content correct; only 1-2 minor issues (content, placement, OR sizing/hierarchy — e.g. a label slightly too small, or one mild collision)
  3 – Half of labels have issues, whether content (wrong text, wrong target, missing, unclear), placement (overlapping, escaping the plot area, clipped), or legibility (uncomfortably small, inconsistent hierarchy)
  2 – Most labels problematic — mislabeled/missing content, badly colliding, or generally too small/cluttered to read comfortably
  1 – No labels, or all wrong/mislabeled/illegible

concept_accuracy:
  5 – All concepts accurate; interactions demonstrate correct relationships; no misinformation
  4 – Main concept correct; ≤1 minor detail wrong or missing
  3 – Main concept present; 2-3 details wrong or missing
  2 – Significant errors or fabrications; would mislead students
  1 – Completely incorrect or misleading

ACTION ITEMS — separate feedback for the generation and the plan:
- action_items: list 2-4 generation-level fixes (broken controls, wrong primitives, missing labels, scale issues, camera/view correction — things fixable without changing the plan)
- plan_action_items: list 0-2 plan-level fixes (wrong projection_type, missing core elements, wrong interaction type for the concept, fundamental misunderstanding — things requiring a revised plan). Use [] if the plan is sound.

Output this exact JSON structure and nothing else:
{
  "discrepancies": [],
  "failure_modes": [],
  "geometry_accuracy": 3,
  "interactivity_usability": 3,
  "faithfulness": 3,
  "label_quality": 3,
  "concept_accuracy": 3,
  "notes": "one concise sentence summarizing the main strengths and weaknesses",
  "action_items": [
    "Specific generation-level fix 1",
    "Specific generation-level fix 2"
  ],
  "plan_action_items": [
    "Specific plan-level fix 1 (or empty array if plan is sound)"
  ]
}

